import itertools

def interleave_lists(a, b):
    sentinel = object()
    result = []
    for x, y in itertools.zip_longest(a, b, fillvalue=sentinel):
        if x is not sentinel:
            result.append(x)
        if y is not sentinel:
            result.append(y)
    return result

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    neg_inf = float('-inf')
    padded = [neg_inf] + list(lst) + [neg_inf]
    count = 0
    for i in range(1, n + 1):
        if padded[i] > padded[i - 1] and padded[i] > padded[i + 1]:
            count += 1
    return count

