def min_swaps_to_sort_desc(arr):
    a = list(arr)
    n = len(a)
    target = sorted(a, reverse=True)
    swaps = 0
    for i in range(n):
        if a[i] != target[i]:
            j = i + 1
            while a[j] != target[i]:
                j += 1
            a[i], a[j] = a[j], a[i]
            swaps += 1
    return swaps

