def days_to_end_of_year(y, m, d):
    def leap(year):
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    lengths = [31, 29 if leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    remaining_in_month = lengths[m - 1] - d
    remaining_full_months = sum(lengths[m:])
    return remaining_in_month + remaining_full_months
